lchapter("H", "주식회사 등의 외부감사에 관한 법률", "Act on External Audit of Stock Companies, etc.", part="외부감사법", law="외부감사법")

section("총칙·외부감사 대상")

lc("LH001", "외부감사법의 목적과 주요 정의", "Purpose and definitions", "제1조 제2조 제3조",
   easy="외감법은 외부감사 대상 회사의 회계처리와 감사인의 회계감사를 규율해 이해관계인을 보호한다. '회사'는 외부감사 대상 주식회사·유한회사, '감사인'은 회계법인과 한국공인회계사회에 등록한 감사반이다.",
   legal="이 법은 외부감사를 받는 회사의 회계처리와 외부감사인의 회계감사에 관하여 필요한 사항을 정함으로써 이해관계인을 보호하고 기업의 건전한 경영과 국민경제의 발전에 이바지함을 목적으로 한다(제1조). '회사'란 외부감사 대상이 되는 주식회사 및 유한회사를, '재무제표'란 재무상태표, 손익계산서 또는 포괄손익계산서 및 대통령령 서류를, '감사인'이란 회계법인 또는 한국공인회계사회에 등록한 감사반을, '임원'에는 이사·감사(감사위원 포함)·집행임원·업무집행지시자 등(상법 제401조의2 제1항)을 포함한다(제2조). 공인회계사의 감사에 관한 자본시장법 규정이 이 법과 다르면 그 규정을 적용하되 회계처리기준은 예외다(제3조 제2항).",
   req="정의 규정.", eff="적용 범위 확정.",
   cmp="감사인: 회계법인 vs 감사반(공인회계사회 등록).",
   ex="업무집행지시자인 회장도 외감법상 '임원'에 해당.",
   tip="감사인·임원의 정의가 출제된다.", trap="개인 공인회계사도 등록 없이 감사인이 될 수 있다고 보는 것.", rel="LH002 LD075")
lq("LH001", "외부감사법상 감사인은 회계법인과 한국공인회계사회에 등록을 한 (______)이다.", "감사반", "제2조 제7호.", art="제2조")
lq("LH001", "외부감사법상 '회사'란 외부감사의 대상이 되는 주식회사 및 (______)를 말한다.", "유한회사", "제2조 제1호.", art="제2조", lv=2)

lc("LH002", "외부감사 대상 회사", "Companies subject to external audit", "제4조",
   easy="주권상장법인, 해당·다음 사업연도에 상장하려는 회사, 자산·부채·종업원수·매출액 등 대통령령 기준에 해당하는 회사는 외부감사를 받아야 한다. 재무제표와 연결재무제표 감사인은 동일해야 한다. 상장되지 않은 공기업·준정부기관은 면제될 수 있다.",
   legal="주권상장법인, 해당 사업연도 또는 다음 사업연도 중에 주권상장법인이 되려는 회사, 그 밖에 직전 사업연도 말의 자산, 부채, 종업원수 또는 매출액 등 대통령령 기준에 해당하는 회사(유한회사는 사원 수 등 추가 기준)는 재무제표를 작성하여 독립된 외부의 감사인(재무제표 및 연결재무제표의 감사인은 동일하여야 한다)에 의한 회계감사를 받아야 한다(제4조 제1항). 공기업·준정부기관 중 주권상장법인이 아닌 회사 등은 받지 아니할 수 있다(제2항).",
   req="대상 요건.", eff="외부감사 의무.",
   exc="구체적 금액 기준은 시행령(2027 시험범위 밖) — 법률 수준만 학습.",
   cmp="재무제표 감사인 = 연결재무제표 감사인(동일).",
   ex="다음 해 상장 예정인 회사는 올해부터 외부감사 대상.",
   tip="법률에 직접 열거된 대상(상장·상장예정)이 출제된다.", trap="재무제표와 연결재무제표 감사인을 달리 선임할 수 있다고 보는 것.", rel="LH001 LH005")
lq("LH002", "외부감사 대상 회사의 재무제표 및 연결재무제표의 감사인은 (______)하여야 한다.", "동일", "제4조 제1항.", art="제4조①")
lq("LH002", "해당 사업연도 또는 다음 사업연도 중에 (______)이 되려는 회사는 외부감사를 받아야 한다.", "주권상장법인", "제4조 제1항 제2호.", art="제4조①", lv=2)

section("회사의 회계처리·내부회계관리제도")

lc("LH003", "회계처리기준과 재무제표 작성 책임", "Accounting standards and preparation", "제5조 제6조 제7조",
   easy="금융위원회는 증권선물위원회 심의를 거쳐 K-IFRS와 일반기업회계기준을 정한다(민간기관에 위탁 가능). 재무제표 작성 책임은 대표이사와 회계담당 임원에게 있고, 감사인은 회사 재무제표를 대신 작성하거나 회계처리 자문을 하면 안 된다.",
   legal="금융위원회는 증권선물위원회의 심의를 거쳐 국제회계기준을 채택한 회계처리기준과 그 밖에 이 법에 따른 회계처리기준을 정하고(제5조 제1항), 이를 민간 법인·단체(회계기준제정기관)에 위탁할 수 있다(제4항). 회사의 대표이사와 회계담당 임원은 재무제표를 작성할 책임이 있고(제6조 제1항), 사업보고서 제출대상법인이 기간 내 감사인에게 재무제표를 제출하지 못하면 사업보고서 공시 후 14일 이내에 사유를 공시하여야 한다(제3항). 감사인 및 소속 공인회계사는 재무제표를 대신 작성하거나 회계처리 자문에 응하는 등의 행위를 해서는 아니 되며 회사도 이를 요구해서는 아니 된다(제6항). 지배회사는 연결재무제표 작성을 위해 종속회사 장부 열람·자료제출 요구·업무재산 조사를 할 수 있다(제7조).",
   req="회사의 재무제표 작성.", eff="위반 시 감사인 지정(제11조) 및 벌칙(제42조).",
   cmp="재무제표 작성 책임(회사) vs 감사 책임(감사인).",
   ex="감사인이 회사 결산 분개를 대신 작성해 주는 것은 금지.", nums="미제출 사유 공시 14일.",
   tip="재무제표 대리작성 금지가 매년 출제된다.", trap="감사인이 회계처리 자문을 할 수 있다고 보는 것.", rel="LH004 LG006")
lq("LH003", "회사의 (______)와 회계담당 임원은 해당 회사의 재무제표를 작성할 책임이 있다.", "대표이사", "제6조 제1항.", art="제6조①")
nr("N-H-001", "LH003", "제6조③", "재무제표 미제출 사유 공시기한", "사업보고서 제출대상법인이 재무제표를 기간 내 감사인에게 제출하지 못한 경우 사업보고서 공시 후 (______) 이내에 그 사유를 공시하여야 한다.", "14일", "", "제6조 제3항.", lv=3)
lq("LH003", "금융위원회는 (______)의 심의를 거쳐 회사의 회계처리기준을 정한다.", "증권선물위원회", "제5조 제1항.", art="제5조①", lv=2)

lc("LH004", "내부회계관리제도", "Internal control over financial reporting", "제8조",
   easy="회사는 내부회계관리규정과 조직을 갖춰야 한다(비상장으로 자산 1천억원 미만 등은 제외). 대표자가 책임지고 상근이사 1명을 내부회계관리자로 지정하며, 매 사업연도 주총·이사회·감사에 운영실태를 보고한다. 감사는 평가해 이사회에 보고하고 평가보고서를 5년간 비치한다. 감사인은 검토하되, 자산 1천억원 이상 상장법인은 감사한다.",
   legal="회사는 내부회계관리규정과 이를 관리·운영하는 조직(내부회계관리제도)을 갖추어야 하나, 주권상장법인이 아닌 회사로서 직전 사업연도 말 자산총액이 1천억원 미만인 회사 등은 그러하지 아니하다(제8조 제1항). 대표자는 내부회계관리제도의 관리·운영을 책임지며 상근이사 1명을 내부회계관리자로 지정하여야 하고(제3항), 사업연도마다 주주총회, 이사회 및 감사에게 운영실태를 보고하여야 한다(제4항). 감사는 운영실태를 평가하여 이사회에 사업연도마다 보고하고 평가보고서를 본점에 5년간 비치하여야 한다(제5항). 감사인은 준수 여부와 운영실태 보고내용을 검토하여야 하나, 주권상장법인(자산총액 1천억원 미만 제외)의 감사인은 감사하여야 한다(제6항).",
   req="외부감사 대상 회사(예외 제외).", eff="미구비·미보고 시 3천만원 이하 과태료(제47조 제2항).",
   cmp="검토(일반) vs 감사(자산 1천억원 이상 상장법인).",
   ex="자산 5천억원 상장회사 → 내부회계관리제도 '감사' 대상.", nums="1천억원 / 평가보고서 5년 / 내부회계관리자 1명.",
   tip="보고 주체·대상과 검토/감사 구분이 출제된다.", trap="내부회계 운영실태를 감사가 주주총회에만 보고한다고 보는 것(감사는 이사회에 보고).", rel="LH003 LD081")
nr("N-H-002", "LH004", "제8조①", "내부회계관리제도 면제 자산기준", "주권상장법인이 아닌 회사로서 직전 사업연도 말의 자산총액이 (______) 미만인 회사는 내부회계관리제도를 갖추지 않아도 된다.", "1천억원", "", "제8조 제1항 단서.")
nr("N-H-003", "LH004", "제8조⑤", "내부회계 평가보고서 비치기간", "회사의 감사는 내부회계관리제도 평가보고서를 해당 회사의 본점에 (______)간 비치하여야 한다.", "5년", "", "제8조 제5항.", lv=3)
